package in.kabadiwala.connect.integration; import in.kabadiwala.connect.model.Payment; import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.http.*; import org.springframework.stereotype.Component; import org.springframework.web.client.RestClient; import javax.crypto.Mac; import javax.crypto.spec.SecretKeySpec; import java.nio.charset.StandardCharsets; import java.util.*; @Component @ConditionalOnProperty(name="app.payment.provider",havingValue="razorpay") public class RazorpayPaymentProvider implements PaymentProvider {private final String key,secret; private final RestClient client=RestClient.create(); public RazorpayPaymentProvider(@Value("${app.payment.razorpay.key-id}")String k,@Value("${app.payment.razorpay.key-secret}")String s){key=k;secret=s;} public String name(){return "RAZORPAY";} public Map<String,Object> initiate(Payment p){String basic=Base64.getEncoder().encodeToString((key+":"+secret).getBytes(StandardCharsets.UTF_8));Map body=client.post().uri("https://api.razorpay.com/v1/orders").header("Authorization","Basic "+basic).contentType(MediaType.APPLICATION_JSON).body(Map.of("amount",Math.round(p.amount*100),"currency","INR","receipt",p.paymentId)).retrieve().body(Map.class);return body==null?Map.of():body;} public boolean verify(String order,String payment,String signature){try{Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));String hex=HexFormat.of().formatHex(m.doFinal((order+"|"+payment).getBytes(StandardCharsets.UTF_8)));return java.security.MessageDigest.isEqual(hex.getBytes(),signature.getBytes());}catch(Exception e){return false;}}}
